const refused = [];
const skipped = [];

for (const issue of issues) {
  const resp = tool("ask_human", {
    id: issue.id,
    question: `Do you approve closing issue ${issue.id}?`
  });
  if (resp.approve) {
    try {
      tool("close_issue", { id: issue.id });
      closed.push(issue.id);
    } catch (e) {
      refused.push({ id: issue.id, reason: e.message || "Close failed" });
    }
  } else {
    skipped.push(issue.id);
  }
}

